#include <bits/stdc++.h>
using namespace std;

int main() {
    int h1, h2, m1, m2;
    scanf("%d:%d", &h1, &m1);
    scanf("%d:%d", &h2, &m2);

    int t1 = h1 * 60 + m1;
    int t2 = h2 * 60 + m2;
    int ans = t2 - t1;

    if (ans >= 60) {
        int r = ans / 60;
        ans %= 60;
        h1 += r;
    }

    m1 += ans;
    cout << h1 << ":" << m1 << '\n';
    return 0;
}

